__device__ __forceinline__ uint4 sk2_decode_raw_v33(uint32_t lw0, uint32_t lw1, uint32_t nw, uint32_t hw) {
  const uint32_t ha = (nw & 0x0f0f0f0fu) | ((hw & 0x0f0f0f0fu) << 4);
  const uint32_t hb = ((nw >> 4) & 0x0f0f0f0fu) | (hw & 0xf0f0f0f0u);
